def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core, _ = core.split('+', 1)
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def cmp_id(a, b):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            an, bn = int(a), int(b)
            return (an > bn) - (an < bn)
        if a_num and not b_num:
            return -1
        if not a_num and b_num:
            return 1
        return (a > b) - (a < b)

    def cmp_pre(a, b):
        # a, b are lists of identifiers or None
        if a is None and b is None:
            return 0
        if a is None:
            return 1  # a has no pre-release, sorts after
        if b is None:
            return -1
        for x, y in zip(a, b):
            c = cmp_id(x, y)
            if c != 0:
                return c
        return (len(a) > len(b)) - (len(a) < len(b))

    def cmp_version(v1, v2):
        m1, n1, p1, pre1 = parse(v1)
        m2, n2, p2, pre2 = parse(v2)
        if m1 != m2:
            return -1 if m1 < m2 else 1
        if n1 != n2:
            return -1 if n1 < n2 else 1
        if p1 != p2:
            return -1 if p1 < p2 else 1
        return cmp_pre(pre1, pre2)

    import functools
    return sorted(versions, key=functools.cmp_to_key(cmp_version))

